#include <iostream>
#include <cstring>
using namespace std;

const int N = 1010;
const int INF = 0x3f3f3f3f;
int g[N][N];

int main() {
    int n, m;
    cin >> n >> m;
    memset(g, 0x3f, sizeof(g));
    for (int i = 1; i <= n; i++) g[i][i] = 0;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u][v] = min(g[u][v], w);
        g[v][u] = min(g[v][u], w);
    }
    int q;
    cin >> q;
    while (q--) {
        int u, v;
        cin >> u >> v;
        if (g[u][v] == INF) cout << "No edge" << endl;
        else cout << "weight=" << g[u][v] << endl;
    }
    return 0;
}

