const int N = 100010, M = 200010;
int head[N], to[M], nxt[M], w[M], cnt;

void addEdge(int u, int v, int weight) {
    cnt++;
    to[cnt] = v;
    w[cnt] = weight;
    nxt[cnt] = head[u];
    head[u] = cnt;
}

int main() {
