#include <iostream>
#include <vector>
using namespace std;

const int N = 100010;
vector<int> adj[N];
bool visited[N];

void dfs(int u) {
    visited[u] = true;
    cout << u << " ";
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(v);
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int components = 0;
    for (int i = 1; i <= n; i++) {
        if (!visited[i]) {
            components++;
            cout << "Component " << components << ": ";
            dfs(i);
            cout << endl;
        }
    }
    cout << "Total components: " << components << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int N = 100010;
vector<int> adj[N];
int dist[N];

void bfs(int start, int n) {
    queue<int> q;
    memset(dist, -1, sizeof(dist));
    dist[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    bfs(s, n);
    for (int i = 1; i <= n; i++) {
        cout << "dist[" << i << "]=" << dist[i] << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int N = 100010;
vector<int> adj[N];
int indegree[N];

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        indegree[v]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }
    vector<int> topo;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        topo.push_back(u);
        for (int v : adj[u]) {
            indegree[v]--;
            if (indegree[v] == 0) {
                q.push(v);
            }
        }
    }
    if ((int)topo.size() == n) {
        cout << "Topological order: ";
        for (int x : topo) cout << x << " ";
        cout << endl;
    } else {
        cout << "Graph has a cycle!" << endl;
    }
    return 0;
}
